esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Attempt withdraw from c by this contract (which is NOT the owner).
    // Parameters:
    //   amount - value to request to withdraw from c
    // We require this test contract has enough balance only when sending Ether to c, but here we don't send Ether to c.
    function run(uint amount) public payable {
        // Observe before state
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        // Top-level state-changing interaction: try to call withdraw(amount) as this contract (not owner)
        bool withdrewReverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrewReverted = true;
        } else {
            withdrewReverted = false;
        }

        // Observe after state
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        // General rule: if withdraw by non-owner reverts then c's balance and depositsCount are unchanged;
        // if it did not revert, then it must have reduced balance by exactly `amount` (or to zero if amount > balance)
        // and depositsCount unchanged. Because withdraw uses transfer which will revert on insufficient funds,
        // a successful call implies beforeBalance >= amount and afterBalance == beforeBalance - amount.
        assert(
            // depositsCount is always unchanged by withdraw from any caller
            afterDeposits == beforeDeposits
            && (
                withdrewReverted
                ? (afterBalance == beforeBalance) // on revert, no balance change
                : (beforeBalance >= amount && afterBalance == beforeBalance - amount) // on success, balance decreased by amount
            )
        );
    }

    receive() external payable {}
}

