// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        bool withdrewReverted;
        try c.withdraw(amount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        uint afterBalance = address(c).balance;
        assertTrue(afterDeposits == beforeDeposits
            && (
                withdrewReverted
                ? (afterBalance == beforeBalance) // on revert, no balance change
                : (beforeBalance >= amount && afterBalance == beforeBalance - amount) // on success, balance decreased by amount
            ));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
